                        columns +="[dbo].[" + myentity.SysName + "].[" + myfield.SystemName + "]";
                        values += " @p" + pcount;
                        SqlParameter param = CreateParameterByType(myfield, value, pcount);
                        parameters.Add(param);

                    }

                }
                if (values != "")
                    values = " VALUES ( " + values+")";
                if (columns != "")
                    columns = " ( " + columns+") ";
                if (tables != "")
                    tables = " INSERT INTO " + tables;
                if (values != "" && tables != "" && values != "")
                {
                    string sql = tables + columns + values ;
                    return database.Execute(sql, parameters.ToArray());

                }

            }


        }
    }
    return status;
}

